package tz.go.bukobamc.meetings.api;
import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException; import tz.go.bukobamc.meetings.model.*; import tz.go.bukobamc.meetings.repo.*; import tz.go.bukobamc.meetings.security.PasswordService; import tz.go.bukobamc.meetings.security.SessionService; import tz.go.bukobamc.meetings.service.AuditService; import tz.go.bukobamc.meetings.service.GuestImportService; import tz.go.bukobamc.meetings.service.MeetingNoticeService; import tz.go.bukobamc.meetings.service.MeetingReportService; import tz.go.bukobamc.meetings.service.NotificationService; import tz.go.bukobamc.meetings.service.OtpService; import jakarta.servlet.http.HttpServletRequest; import java.io.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api") public class MeetingController {
 private final UserRepository users; private final MeetingRepository meetings; private final GuestRepository guests; private final InvitationRepository invitations; private final OTPVerificationRepository otps; private final QRSessionRepository qrSessions; private final AttendanceRecordRepository attendance; private final SessionService sessions; private final NotificationService notifications; private final PasswordService passwords; private final OtpService otpService; private final AuditService audit; private final GuestImportService guestImport; private final MeetingReportService reports; private final MeetingNoticeService notices; private final String baseUrl,defaultWhatsappSender,defaultEmailSender,appEnv; private final boolean whatsappEnabled;
 public MeetingController(UserRepository u,MeetingRepository m,GuestRepository g,InvitationRepository i,OTPVerificationRepository o,QRSessionRepository q,AttendanceRecordRepository a,SessionService s,NotificationService n,PasswordService pw,OtpService otp,AuditService aud,GuestImportService gi,MeetingReportService reports,MeetingNoticeService notices,@Value("${bmc.public-base-url}")String b,@Value("${bmc.default-whatsapp-sender}")String ws,@Value("${bmc.default-email-sender}")String es,@Value("${bmc.whatsapp-enabled:false}")boolean we,@Value("${APP_ENV:development}")String env){users=u;meetings=m;guests=g;invitations=i;otps=o;qrSessions=q;attendance=a;sessions=s;notifications=n;passwords=pw;otpService=otp;audit=aud;guestImport=gi;this.reports=reports;this.notices=notices;baseUrl=b;defaultWhatsappSender=ws;defaultEmailSender=es;whatsappEnabled=we;appEnv=env;}
 private User auth(String h){return sessions.require(h);} private static String tokenHash(String x){return PasswordService.legacySha256(x);} private static String token(){return Base64.getUrlEncoder().withoutPadding().encodeToString(UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8));} private static boolean past(Meeting m){return m.endAt!=null&&!m.endAt.isAfter(OffsetDateTime.now());} private static boolean open(Meeting m){OffsetDateTime n=OffsetDateTime.now();return m.startAt!=null&&!n.isBefore(m.startAt.minusMinutes(30))&&!n.isAfter(m.startAt.plusMinutes(30));} private static String window(Meeting m){OffsetDateTime n=OffsetDateTime.now();if(n.isBefore(m.startAt.minusMinutes(30)))return "Check-in is not open yet. Check-in will open 30 minutes before the meeting starts.";if(n.isAfter(m.startAt.plusMinutes(30)))return "Check-in has closed. The attendance check-in period for this meeting has ended.";return "Check-in is open.";} private static void editable(Meeting m){if("cancelled".equals(m.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cancelled meetings are read-only");if(past(m))throw new ResponseStatusException(HttpStatus.CONFLICT,"Past meetings are read-only");} private static void owner(User u,Meeting m){if(!Objects.equals(u.id,m.createdBy))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the meeting creator may manage this meeting");} private static String ip(HttpServletRequest r){String f=r.getHeader("X-Forwarded-For");return f!=null&&!f.isBlank()?f.split(",")[0].trim():r.getRemoteAddr();}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","service","bmc-meetings-springboot");}
 public record Login(String email,String password){} public record Register(String name,String email,String phone,String password){} public record Verify(String email,String channel,String code){} public record Resend(String email,String channel){} public record ProfileIn(String name,String phone){} public record MeetingIn(String title,String purpose,OffsetDateTime start_at,OffsetDateTime end_at,String location,String map_link,String virtual_link,String department,String meeting_type,String priority,String status){} public record GuestIn(String name,String phone,String email,String role_title,String organization){} public record RsvpIn(String status,String reason,String language){} public record AttendanceIn(String personal_token,String qr_payload){} public record NoticeIn(String message){} public record CancelIn(String reason){}
 private String otp(User u,String c){String code=otpService.issueAlphanumeric(u,c);if("email".equals(c))notifications.verificationEmail(u.email,u.name,code,"BMC Meetings – Verify your registration","Verify your registration","Enter this code to complete your BMC Meetings account registration.");else notifications.whatsappQuiet(u.phone,"Your verification code is "+code+". It expires in 10 minutes.");return code;}
 @PostMapping("/auth/register") public Object register(@RequestBody Register x,HttpServletRequest req){String email=x.email().trim().toLowerCase();var existing=users.findByEmail(email);if(existing.isPresent()&&existing.get().active&&"active".equals(existing.get().status))throw new ResponseStatusException(HttpStatus.CONFLICT,"That email address is already in use.");User u=existing.orElseGet(User::new);u.name=x.name();u.email=email;u.phone=x.phone().trim();u.passwordHash=passwords.hash(x.password());u.role="organizer";u.status="pending";u.active=false;u.emailVerified=false;u.phoneVerified=!whatsappEnabled;u.createdAt=OffsetDateTime.now();u=users.save(u);String code=otp(u,"email");if(whatsappEnabled)otp(u,"phone");audit.record(u,"REGISTER","Organizer registration started",ip(req));Map<String,Object> r=new LinkedHashMap<>();r.put("status","pending");r.put("message","Enter the Email OTP"+(whatsappEnabled?" and WhatsApp OTP":""));if("development".equalsIgnoreCase(appEnv))r.put("development_email_otp",code);return r;}
 @PostMapping("/auth/verify") public Object verify(@RequestBody Verify x,HttpServletRequest req){User u=users.findByEmail(x.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Registration not found"));otpService.verify(u,x.channel(),x.code(),"Invalid or expired OTP");if("email".equals(x.channel()))u.emailVerified=true;else u.phoneVerified=true;if(u.emailVerified&&(u.phoneVerified||!whatsappEnabled)){u.status="active";u.active=true;audit.record(u,"REGISTER_VERIFY","Account activated",ip(req));}users.save(u);return Map.of("status",u.status,"verified",x.channel());}
 @PostMapping("/auth/resend") public Object resend(@RequestBody Resend x){User u=users.findByEmail(x.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Registration not found"));String c=otp(u,x.channel());return Map.of("status","sent","channel",x.channel(),"development_email_otp","email".equals(x.channel())&&"development".equalsIgnoreCase(appEnv)?c:"");}
 @PostMapping("/auth/login") public Object login(@RequestBody Login x,HttpServletRequest req){User u=users.findByEmail(x.email().trim().toLowerCase()).filter(a->a.active&&"active".equals(a.status)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email, password, or unverified account"));if(!passwords.matches(x.password(),u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email, password, or unverified account");if(passwords.isLegacyHash(u.passwordHash)){u.passwordHash=passwords.hash(x.password());users.save(u);}String token=sessions.create(u);audit.record(u,"LOGIN","Successful sign-in",ip(req));return Map.of("access_token",token,"user",Map.of("name",u.name,"role",u.role,"email",u.email));}
 @GetMapping("/me") public Object me(@RequestHeader("Authorization")String h){User u=auth(h);return Map.of("name",u.name,"role",u.role,"email",u.email,"phone",Objects.toString(u.phone,""),"emailVerified",u.emailVerified);} @PutMapping("/me") public Object profile(@RequestHeader("Authorization")String h,@RequestBody ProfileIn x,HttpServletRequest req){User u=auth(h);if(x.name()!=null&&!x.name().isBlank())u.name=x.name();if(x.phone()!=null&&!x.phone().isBlank())u.phone=x.phone();users.save(u);audit.record(u,"PROFILE_UPDATE","Updated profile details",ip(req));return Map.of("name",u.name,"phone",Objects.toString(u.phone,""),"email",u.email);}
 public record EmailChange(String email,String code){}
 @PostMapping("/me/email-change/request") public Object requestEmailChange(@RequestHeader("Authorization")String h,@RequestBody EmailChange x){User u=auth(h);String email=x.email().trim().toLowerCase();if(email.equals(u.email))return Map.of("status","unchanged","message","This is already your verified email address.");if(users.findByEmail(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"That email address is already in use.");String code=otpService.issueNumeric(u,"email_change");notifications.verificationEmail(email,u.name,code,"BMC Meetings – Confirm your new email","Confirm your new email","Enter this code to verify your new email address for BMC Meetings.");Map<String,Object> r=new LinkedHashMap<>();r.put("status","otp_required");r.put("email",email);if("development".equalsIgnoreCase(appEnv))r.put("development_email_otp",code);return r;}
 @PostMapping("/me/email-change/verify") public Object verifyEmailChange(@RequestHeader("Authorization")String h,@RequestBody EmailChange x,HttpServletRequest req){User u=auth(h);String email=x.email().trim().toLowerCase();if(users.findByEmail(email).filter(a->!Objects.equals(a.id,u.id)).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"That email address is already in use.");otpService.verify(u,"email_change",x.code(),"Invalid or expired email verification code.");u.email=email;u.emailVerified=true;users.save(u);audit.record(u,"EMAIL_CHANGE","Updated email to "+email,ip(req));return Map.of("status","updated","email",u.email,"message","Email address updated and verified successfully.");}
 @GetMapping("/meetings") public Object list(@RequestHeader("Authorization")String h){User u=auth(h);return meetings.findAll().stream().filter(m->"admin".equals(u.role)||Objects.equals(m.createdBy,u.id)).map(m->Map.of("id",m.id,"reference",m.reference,"title",m.title,"start_at",m.startAt,"end_at",m.endAt,"location",Objects.toString(m.location,""),"status",m.status,"past",past(m),"guest_count",guests.countByMeetingId(m.id))).toList();}
 @PostMapping("/meetings") public Object create(@RequestHeader("Authorization")String h,@RequestBody MeetingIn x,HttpServletRequest req){User u=auth(h);if(x.start_at()==null||x.end_at()==null||x.start_at().isBefore(OffsetDateTime.now())||!x.end_at().isAfter(x.start_at()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Valid future start and end times are required");Meeting m=new Meeting();m.reference="BMC-"+LocalDate.now()+"-"+UUID.randomUUID().toString().substring(0,4).toUpperCase();m.createdBy=u.id;m.title=x.title();m.purpose=x.purpose();m.startAt=x.start_at();m.endAt=x.end_at();m.location=x.location();m.mapLink=x.map_link();m.virtualLink=x.virtual_link();m.department=x.department();m.meetingType=x.meeting_type()==null?"internal":x.meeting_type();m.priority=x.priority()==null?"normal":x.priority();m.status=x.status()==null?"draft":x.status();m=meetings.save(m);audit.record(u,"MEETING_CREATE","Created meeting "+m.reference,ip(req));return Map.of("id",m.id,"reference",m.reference);}
 @PutMapping("/meetings/{id}") public Object update(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody MeetingIn x,HttpServletRequest req){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);editable(m);if(x.start_at()==null||x.end_at()==null||!x.end_at().isAfter(x.start_at()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Valid start and end times are required");m.title=x.title();m.purpose=x.purpose();m.startAt=x.start_at();m.endAt=x.end_at();m.location=x.location();m.mapLink=x.map_link();m.virtualLink=x.virtual_link();m.department=x.department();if(x.meeting_type()!=null)m.meetingType=x.meeting_type();if(x.priority()!=null)m.priority=x.priority();if(x.status()!=null)m.status=x.status();meetings.save(m);audit.record(u,"MEETING_UPDATE","Updated meeting "+m.reference,ip(req));return Map.of("id",m.id,"reference",m.reference,"status",m.status);}
 @GetMapping("/meetings/{id}") public Object detail(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role))owner(u,m);List<Invitation> ins=invitations.findByMeetingId(id);List<AttendanceRecord> ars=attendance.findByMeetingId(id);List<Map<String,Object>> gs=new ArrayList<>();for(Guest g:guests.findByMeetingId(id)){Invitation i=ins.stream().filter(v->Objects.equals(v.guest.id,g.id)).findFirst().orElse(null);AttendanceRecord a=ars.stream().filter(v->Objects.equals(v.participantId,g.id)&&v.used).findFirst().orElse(null);gs.add(Map.of("id",g.id,"name",g.name,"phone",Objects.toString(g.phone,""),"email",Objects.toString(g.email,""),"organization",Objects.toString(g.organization,""),"status",i!=null&&i.response!=null?i.response.status:"no_response","attended",a!=null,"checked_in_at",a==null?"":a.signedInAt));}long n=gs.stream().filter(v->Boolean.TRUE.equals(v.get("attended"))).count();Map<String,Object> r=new LinkedHashMap<>();r.put("id",m.id);r.put("reference",m.reference);r.put("title",m.title);r.put("purpose",Objects.toString(m.purpose,""));r.put("start_at",m.startAt);r.put("end_at",m.endAt);r.put("location",Objects.toString(m.location,""));r.put("map_link",Objects.toString(m.mapLink,""));r.put("virtual_link",Objects.toString(m.virtualLink,""));r.put("department",Objects.toString(m.department,""));r.put("meeting_type",Objects.toString(m.meetingType,"internal"));r.put("priority",Objects.toString(m.priority,"normal"));r.put("status",Objects.toString(m.status,"draft"));r.put("past",past(m));r.put("can_manage",Objects.equals(u.id,m.createdBy)&&!"cancelled".equals(m.status));r.put("cancellation_reason",Objects.toString(m.cancellationReason,""));r.put("cancelled_at",m.cancelledAt);r.put("counts",Map.of("confirmed",gs.stream().filter(v->"confirmed".equals(v.get("status"))).count(),"declined",gs.stream().filter(v->"declined".equals(v.get("status"))).count(),"tentative",gs.stream().filter(v->"tentative".equals(v.get("status"))).count(),"no_response",gs.stream().filter(v->"no_response".equals(v.get("status"))).count()));r.put("guests",gs);r.put("attendance",Map.of("invited",gs.size(),"attended",n,"not_attended",gs.size()-n,"percentage",gs.isEmpty()?0:Math.round(n*10000.0/gs.size())/100.0));return r;}
 @PostMapping("/meetings/{id}/guests") public Object guest(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody GuestIn x){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);editable(m);if((x.phone()==null||x.phone().isBlank())&&(x.email()==null||x.email().isBlank()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Phone or email is required");Guest g=new Guest();g.meeting=m;g.name=x.name();g.phone=x.phone();g.email=x.email();g.roleTitle=x.role_title();g.organization=x.organization();return Map.of("id",guests.save(g).id);}
 @PostMapping("/meetings/{id}/guests/import") public Object importCsv(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestParam MultipartFile file,HttpServletRequest req)throws IOException{User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);editable(m);Map<String,Object> result=guestImport.importGuests(m,file);audit.record(u,"GUEST_IMPORT","Imported guests for "+m.reference+" ("+result.get("added")+" added)",ip(req));return result;}
 @PostMapping("/meetings/{id}/send-invites") public Object invite(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);editable(m);List<Map<String,Object>> out=new ArrayList<>();for(Guest g:guests.findByMeetingId(id)){String raw=token();Invitation i=new Invitation();i.meeting=m;i.guest=g;i.tokenHash=tokenHash(raw);i.deliveryStatus="sent";i.sentAt=OffsetDateTime.now();invitations.save(i);String link=baseUrl+"/attendance.html?token="+raw;String plain=notifications.meetingInvitationPlain(g,m,u.name,link);if(g.phone!=null&&!g.phone.isBlank())notifications.whatsappQuiet(g.phone,plain);notifications.meetingInvitationEmail(g,m,u.name,link);out.add(Map.of("guest",g.name,"personal_sign_in_link",link,"channel",g.phone!=null&&!g.phone.isBlank()&&g.email!=null&&!g.email.isBlank()?"whatsapp_and_email":g.phone!=null&&!g.phone.isBlank()?"whatsapp":"email","status","sent"));}m.status="published";meetings.save(m);return Map.of("sent",out.size(),"results",out);}
 @GetMapping("/rsvp/{token}") public Object rsvpInfo(@PathVariable String token){Invitation i=invitations.findByTokenHash(tokenHash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid invitation link"));Meeting m=i.meeting;return Map.of("meeting",Map.of("reference",m.reference,"title",m.title,"purpose",Objects.toString(m.purpose,""),"start_at",m.startAt,"end_at",m.endAt,"location",Objects.toString(m.location,"")),"guest",Map.of("name",i.guest.name),"token",token);}
 @PostMapping("/rsvp/{token}") public Object rsvp(@PathVariable String token,@RequestBody RsvpIn x){if(!Set.of("confirmed","declined","tentative").contains(x.status()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid RSVP status");Invitation i=invitations.findByTokenHash(tokenHash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid invitation link"));RsvpResponse r=i.response==null?new RsvpResponse():i.response;r.invitation=i;r.status=x.status();r.reason=x.reason();r.language=x.language()==null?"en":x.language();r.respondedAt=OffsetDateTime.now();i.response=r;invitations.save(i);return Map.of("status","saved","message","RSVP recorded");}
 @GetMapping("/meetings/{id}/attendance/qr") public Object attendanceQr(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);if(!open(m))throw new ResponseStatusException(HttpStatus.CONFLICT,window(m));OffsetDateTime now=OffsetDateTime.now();String raw=token();QRSession q=new QRSession();q.meeting=m;q.sessionTokenHash=tokenHash(raw);q.issuedAt=now;q.expiresAt=now.plusSeconds(45);qrSessions.save(q);String payload="{\"meetingId\":"+m.id+",\"sessionToken\":\""+raw+"\",\"expiresAt\":\""+q.expiresAt+"\"}";return Map.of("meeting_id",m.id,"payload",payload,"issued_at",now,"expires_at",q.expiresAt);}
 @GetMapping("/attendance/{token}") public Object attendanceInfo(@PathVariable String token){Invitation i=invitations.findByTokenHash(tokenHash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal check-in link is invalid or expired"));AttendanceRecord a=attendance.findByMeetingIdAndParticipantId(i.meeting.id,i.guest.id).orElse(null);return Map.of("meeting",Map.of("title",i.meeting.title,"purpose",Objects.toString(i.meeting.purpose,""),"start_at",i.meeting.startAt,"end_at",i.meeting.endAt,"location",Objects.toString(i.meeting.location,"")),"participant",i.guest.name,"attended",a!=null&&a.used,"check_in_open",open(i.meeting),"message",window(i.meeting));}
 @PostMapping("/attendance/sign-in") public Object signIn(@RequestBody AttendanceIn x){Invitation i=invitations.findByTokenHash(tokenHash(x.personal_token())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal check-in link is invalid or expired"));if(!open(i.meeting))throw new ResponseStatusException(HttpStatus.CONFLICT,window(i.meeting));AttendanceRecord e=attendance.findByMeetingIdAndParticipantId(i.meeting.id,i.guest.id).orElse(null);if(e!=null&&e.used)throw new ResponseStatusException(HttpStatus.CONFLICT,"You are already marked as attended");Map<?,?> p;try{p=new ObjectMapper().readValue(x.qr_payload(),Map.class);}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid Attendance QR Code");}if(!Objects.equals(String.valueOf(p.get("meetingId")),String.valueOf(i.meeting.id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Wrong meeting QR Code");QRSession q=qrSessions.findBySessionTokenHash(tokenHash(String.valueOf(p.get("sessionToken")))).orElseThrow(()->new ResponseStatusException(HttpStatus.GONE,"QR expired — rescan the live Attendance QR Code"));if(!q.meeting.id.equals(i.meeting.id)||q.expiresAt.isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.GONE,"QR expired — rescan the live Attendance QR Code");AttendanceRecord a=e==null?new AttendanceRecord():e;a.meeting=i.meeting;a.participantId=i.guest.id;a.personalTokenHash=tokenHash(x.personal_token());a.signedInAt=OffsetDateTime.now();a.used=true;attendance.save(a);return Map.of("status","attended","signed_in_at",a.signedInAt,"message","Attendance recorded successfully. Thank you!");}
 @GetMapping(value="/meetings/{id}/report.csv",produces="text/csv") public ResponseEntity<String> report(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role))owner(u,m);List<Invitation> ins=invitations.findByMeetingId(id);List<AttendanceRecord> ars=attendance.findByMeetingId(id);StringBuilder s=new StringBuilder("Meeting reference,"+m.reference+"\nName,Phone,Email,Invitation status,Attendance status,Check-in date,Check-in time\n");for(Guest g:guests.findByMeetingId(id)){Invitation i=ins.stream().filter(z->Objects.equals(z.guest.id,g.id)).findFirst().orElse(null);AttendanceRecord a=ars.stream().filter(z->Objects.equals(z.participantId,g.id)&&z.used).findFirst().orElse(null);s.append(String.join(",",csv(g.name),csv(g.phone),csv(g.email),i!=null&&i.response!=null?i.response.status:"no_response",a==null?"not_attended":"attended",a==null?"":a.signedInAt.toLocalDate().toString(),a==null?"":a.signedInAt.toLocalTime().toString())).append("\n");}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+m.reference+"-attendance.csv").body(s.toString());}
 @GetMapping(value="/meetings/{id}/report.pdf",produces="application/pdf") public ResponseEntity<byte[]> reportPdf(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role))owner(u,m);byte[] body=reports.buildPdf(m,guests.findByMeetingId(id),invitations.findByMeetingId(id),attendance.findByMeetingId(id));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+m.reference+"-attendance.pdf").contentType(MediaType.APPLICATION_PDF).body(body);}
 @PostMapping("/meetings/{id}/notify-reschedule") public Object notifyReschedule(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody NoticeIn x,HttpServletRequest req){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);editable(m);int sent=notices.notifyReschedule(m,guests.findByMeetingId(id),x.message());audit.record(u,"MEETING_RESCHEDULE_NOTICE","Notified "+sent+" guest(s) for "+m.reference,ip(req));return Map.of("sent",sent,"message","Reschedule notice sent to guests");}
 @PostMapping("/meetings/{id}/cancel") public Object cancel(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody CancelIn x,HttpServletRequest req){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));owner(u,m);editable(m);m.status="cancelled";m.cancellationReason=x.reason()==null?"":x.reason().trim();m.cancelledAt=OffsetDateTime.now();meetings.save(m);int sent=notices.notifyCancellation(m,guests.findByMeetingId(id),m.cancellationReason);audit.record(u,"MEETING_CANCEL","Cancelled "+m.reference+" and notified "+sent+" guest(s)",ip(req));return Map.of("status","cancelled","sent",sent,"reference",m.reference);} private static String csv(String x){return "\""+Objects.toString(x,"").replace("\"","\"\"")+"\"";}
 @GetMapping("/admin/accounts") public Object adminAccounts(@RequestHeader("Authorization")String h){User u=auth(h);if(!"admin".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin access required");return users.findAll().stream().map(x->Map.of("id",x.id,"name",Objects.toString(x.name,""),"email",x.email,"phone",Objects.toString(x.phone,""),"role",x.role,"status",x.status,"active",x.active)).toList();}
 @GetMapping("/admin/attendance") public Object adminAttendance(@RequestHeader("Authorization")String h){User u=auth(h);if(!"admin".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin access required");return attendance.findAll().stream().map(a->{Guest g=guests.findById(a.participantId).orElse(null);Meeting m=a.meeting;Map<String,Object> row=new LinkedHashMap<>();row.put("meeting_id",m.id);row.put("meeting_reference",m.reference);row.put("meeting_title",m.title);row.put("participant_id",a.participantId);row.put("guest_name",g!=null?g.name:"");row.put("guest_phone",g!=null?Objects.toString(g.phone,""):"");row.put("checked_in_at",a.signedInAt);row.put("attended",a.used);return row;}).toList();}
 @PutMapping("/admin/accounts/{id}") public Object updateAccount(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody Map<String,Object> body){User u=auth(h);if(!"admin".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin access required");User target=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Account not found"));if(body.get("role")!=null)target.role=String.valueOf(body.get("role"));if(body.get("active")!=null)target.active=Boolean.parseBoolean(String.valueOf(body.get("active")));target.status=target.active?"active":"inactive";users.save(target);return Map.of("id",target.id,"role",target.role,"status",target.status,"active",target.active);}
 @GetMapping("/admin/audit-logs") public Object auditLogs(@RequestHeader("Authorization")String h){User u=auth(h);if(!"admin".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin access required");return audit.findRecent();}
}
